mapper.sql:
  		where
			1=1

		and t.product = #{product}



		and t.job_id = #{jobId}


		and instr(t.job_id, #{lJobId}) > 0



		and t.job_ins_id = #{jobInsId}


		and instr(t.job_ins_id, #{lJobInsId}) > 0



		and t.batch = #{batch}


		and instr(t.batch, #{lBatch}) > 0



		and t.job_state = #{state}



		and exists (
      		select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr 
        		where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id 
          			and tp.p_id=t.product and tsu.login_name=#{loginName}
		)  

		order by t.begin_time desc

mapper.select:
select distinct t.batch as 'BATCH' from ww_job_instance t where 1=1
and t.product = #{product}
and instr(t.batch, #{lBatch}) > 0

mapper.delete:
    delete 
    from ww_job_instance 
    where 1=1

	and job_ins_id = #{jobInsId}


	and product = #{product}


	and batch = #{batch}

delete 
from ww_job_instance 
where product = #{product} and batch = #{batch}

mapper.update:
    update ww_job_instance t

    		t.properties = #{properties,jdbcType=VARCHAR},
    		t.parameters = #{parameters,jdbcType=VARCHAR},
    		t.job_state = #{state,jdbcType=INTEGER},
    		t.is_paused = #{pause,jdbcType=INTEGER}

	where t.job_ins_id = #{jobInsId}

mapper.select:
select t.job_ins_id, t.product, t.job_id, t.job_state, t.job_name, t.job_mode, t.batch, t.parameters, t.properties, t.accut_date, t.title, t.is_paused, t.version, t.init_time, t.begin_time, t.end_time, t.creator, t.create_time, t.schedule_rid from ww_job_instance t where 1=1
and 1=2
and t.product = #{product}
and t.batch = #{batch}
and exists ( select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id and tp.p_id=t.product and tsu.login_name=#{loginName} )
order by t.init_time desc

select j.batch as "BATCH",max(j.init_time) from ww_job_instance j where 1=1
and j.product = #{product}
group by j.batch order by max(j.init_time) desc
